import React, { createContext, useContext, useState, useEffect } from 'react';

const NewsContext = createContext();

export const useNews = () => {
  const context = useContext(NewsContext);
  if (!context) throw new Error('useNews must be used within NewsProvider');
  return context;
};

export const NewsProvider = ({ children }) => {
  const [news, setNews] = useState(() => {
    const saved = localStorage.getItem('dl-news');
    return saved ? JSON.parse(saved) : [
      {
        id: 1,
        title: '🆕 آپدیت بزرگ سرور دارک لایت',
        titleEn: '🆕 DarkLight Server Major Update',
        content: 'سرور به نسخه 2.0 با قابلیت‌های جدید آپدیت شد.',
        contentEn: 'Server updated to version 2.0 with new features.',
        date: '2026-05-10',
        category: 'update',
        published: true
      },
      {
        id: 2,
        title: '🎉 ایونت ویژه آخر هفته',
        titleEn: '🎉 Special Weekend Event',
        content: 'این هفته ایونت 2x XP داریم! از دست ندید.',
        contentEn: 'We have 2x XP event this week! Don\'t miss it.',
        date: '2026-05-08',
        category: 'event',
        published: true
      },
      {
        id: 3,
        title: '📋 بروزرسانی قوانین سرور',
        titleEn: '📋 Server Rules Update',
        content: 'لطفاً قوانین جدید سرور را مطالعه کنید.',
        contentEn: 'Please review the new server rules.',
        date: '2026-05-05',
        category: 'general',
        published: true
      }
    ];
  });

  // ذخیره توی localStorage هر وقت news تغییر کنه
  useEffect(() => {
    localStorage.setItem('dl-news', JSON.stringify(news));
  }, [news]);

  const addNews = (newsItem) => {
    const newItem = {
      ...newsItem,
      id: Date.now(),
      date: new Date().toISOString().split('T')[0],
      published: true,
    };
    setNews(prev => [newItem, ...prev]);
    return newItem;
  };

  const updateNews = (id, updatedItem) => {
    setNews(prev => prev.map(item => item.id === id ? { ...item, ...updatedItem } : item));
  };

  const deleteNews = (id) => {
    setNews(prev => prev.filter(item => item.id !== id));
  };

  const getNews = () => news;

  return (
    <NewsContext.Provider value={{ news, addNews, updateNews, deleteNews, getNews }}>
      {children}
    </NewsContext.Provider>
  );
};
